 "content": "def _bands(n, occupied):
    out = []
    start = None
    for i in range(n + 1):
        active = i < n and occupied(i)
        if active and start is None:
            start = i
        elif not active and start is not None:
            out.append((start, i - 1))
            start = None
    return out


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    row_bands = _bands(h, lambda r: any(g[r][c] != 0 for c in range(w)))
    col_bands = _bands(w, lambda c: any(g[r][c] != 0 for r in range(h)))
    centers = {}
    for ri, (r0, r1) in enumerate(row_bands):
        for ci, (c0, c1) in enumerate(col_bands):
            # Ignore truncated edge panels; complete tiles have a recognizable center.
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            r, c = (r0 + r1) // 2, (c0 + c1) // 2
            centers[(ri, ci)] = (r, c, g[r][c])

    # Connect equal-colored panel centers in each shared row/column, drawing
    # only through zero-valued separators and preserving all panel contents.
    for (ri, ci), (r, c, color) in centers.items():
        if color == 0:
            continue
        for cj in range(ci + 1, len(col_bands)):
            other = centers.get((ri, cj))
            if other and other[2] == color:
                for x in range(c + 1, other[1]):
                    if g[r][x] == 0:
                        g[r][x] = color
        for rj in range(ri + 1, len(row_bands)):
            other = centers.get((rj, ci))
            if other and other[2] == color:
                for y in range(r + 1, other[0]):
                    if g[y][c] == 0:
                        g[y][c] = color
    return g

